WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What is a constitution?', 'A set of rules that establishes the structure and powers of government and the relationship between the state and citizens.', 1),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What is an uncodified constitution?', 'A constitution not contained in a single document, drawn from several sources.', 2),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What is an unentrenched constitution?', 'A constitution that can be changed by ordinary legislation, without special procedures.', 3),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What is a unitary constitution?', 'Sovereignty lies with a central authority, which may delegate but not share power.', 4),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What are the sources of the UK constitution?', 'Statute law, common law, conventions, authoritative works and treaties.', 5),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What is statute law?', 'Laws passed by Parliament, e.g. the Human Rights Act 1998.', 6),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What is common law?', 'Law based on judicial decisions and precedent.', 7),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What is a convention?', 'An unwritten rule that is followed by custom, e.g. the monarch gives royal assent to bills.', 8),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What is an authoritative work?', 'A written text explaining how the constitution works, e.g. Bagehot''s The English Constitution or Erskine May.', 9),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What is the principle of parliamentary sovereignty?', 'Parliament can make or unmake any law, and no Parliament can bind its successors.', 10),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What is the rule of law in the UK constitution?', 'All are equal before the law, no one is above the law, and punishment only follows a breach of law.', 11),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What was the Magna Carta (1215)?', 'A charter limiting royal power and establishing that the monarch is subject to the law.', 12),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What was the Bill of Rights 1689?', 'It established parliamentary sovereignty over the monarch and rights such as free elections.', 13),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What was devolution in 1998?', 'The transfer of powers from Westminster to a Scottish Parliament, a Welsh Assembly and a Northern Ireland Assembly.', 14),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What was the Human Rights Act 1998?', 'It incorporated the European Convention on Human Rights into UK law.', 15),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What was the House of Lords Act 1999?', 'It removed all but 92 hereditary peers from the House of Lords.', 16),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What was the Fixed-term Parliaments Act 2011?', 'It set five-year fixed terms and restricted early elections; it was repealed by the Dissolution and Calling of Parliament Act 2022.', 17),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What is the West Lothian Question?', 'Why Scottish MPs can vote on English-only matters while English MPs can''t vote on devolved Scottish matters.', 18),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What was English Votes for English Laws (EVEL)?', 'A 2015 procedure giving English MPs a veto on England-only laws; it was abolished in 2021.', 19),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What are the arguments for a codified constitution?', 'Clarity, protection of rights, limits on government power, and education of citizens.', 20),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What are the arguments against a codified constitution?', 'Loss of flexibility, judges gaining political power, and difficulty agreeing on its content.', 21),
  ('Politics', 'AQA', 'alevel', '1.1', 'The Constitution', 'What is the Sewel Convention?', 'Westminster will not normally legislate on devolved matters without the consent of the devolved legislature.', 22),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is the House of Commons?', 'The elected lower chamber of Parliament, with 650 MPs.', 1),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is the House of Lords?', 'The unelected upper chamber, made up of life peers, hereditary peers and bishops.', 2),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What are the functions of Parliament?', 'Legislation, scrutiny of the executive, representation, and debate.', 3),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is the legislative process in the UK?', 'First reading, second reading, committee stage, report stage, third reading, then the other House, and royal assent.', 4),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is a Public Bill Committee?', 'A committee that examines bills line by line after second reading.', 5),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is a select committee?', 'A committee that scrutinises government departments or policy areas.', 6),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is Prime Minister''s Questions?', 'A weekly session where MPs question the Prime Minister.', 7),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is the role of the opposition?', 'To scrutinise and criticise the government and present itself as an alternative government.', 8),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is an Opposition Day?', 'Days (20 per session) when opposition parties choose the topics for debate.', 9),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is the Backbench Business Committee?', 'Created in 2010, it schedules debates chosen by backbench MPs.', 10),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is a Private Member''s Bill?', 'A bill introduced by a backbench MP or peer rather than the government.', 11),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is a ten-minute rule bill?', 'A Private Member''s Bill introduced with a short speech, often used to raise awareness.', 12),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is the role of the whips?', 'They maintain party discipline and ensure MPs vote with the party.', 13),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is a backbench rebellion?', 'When MPs vote against their party''s position.', 14),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is the role of MPs?', 'Representing constituents, scrutinising government, legislating and supporting their party.', 15),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is the trustee model of representation?', 'MPs use their own judgement on behalf of constituents (Burke).', 16),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is the delegate model of representation?', 'MPs act according to the wishes of their constituents.', 17),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is the mandate model of representation?', 'MPs are elected to deliver the manifesto of their party.', 18),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What are the powers of the House of Lords?', 'It can delay most legislation for about a year, revise bills, scrutinise government and hold debates.', 19),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What are the arguments for an elected House of Lords?', 'Democratic legitimacy, accountability, and ending patronage.', 20),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What are the arguments against an elected House of Lords?', 'It could challenge the Commons, lose expertise, and create gridlock.', 21),
  ('Politics', 'AQA', 'alevel', '1.2', 'Parliament', 'What is a life peer?', 'A member of the House of Lords appointed for life, whose title is not inherited.', 22),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What is the Cabinet?', 'The committee of senior ministers, chaired by the Prime Minister, that makes key decisions.', 1),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What is the Prime Minister?', 'The head of government, usually the leader of the largest party in the House of Commons.', 2),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What are the powers of the Prime Minister?', 'Appointing ministers, setting the agenda, controlling Cabinet, leading the party, and using the royal prerogative.', 3),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What are the constraints on the Prime Minister?', 'Size of majority, party unity, public opinion, events, Cabinet, and the media.', 4),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What is the core executive?', 'The network of institutions and people at the centre of government, including the PM, Cabinet, senior civil servants and advisers.', 5),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What is a secondary legislation?', 'Rules made by ministers under powers granted by an Act of Parliament (statutory instruments).', 6),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What is the civil service?', 'Permanent, politically neutral officials who implement government policy.', 7),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What is collective ministerial responsibility?', 'Ministers must publicly support all government decisions or resign.', 8),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What is individual ministerial responsibility?', 'Ministers are responsible for their own conduct and the actions of their department.', 9),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'Give an example of a resignation due to collective responsibility.', 'Robin Cook resigned in 2003 over the Iraq War.', 10),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'Give an example of a resignation over personal conduct.', 'Matt Hancock resigned in 2021 after breaching COVID guidance.', 11),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What is a Cabinet reshuffle?', 'When the Prime Minister changes the roles of ministers.', 12),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What are special advisers?', 'Political appointees who advise ministers and are not politically neutral, e.g. Dominic Cummings.', 13),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What is prime ministerial government?', 'The view that the PM dominates the executive, rather than Cabinet.', 14),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What is Cabinet government?', 'The view that decisions are made collectively by the Cabinet.', 15),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What is presidentialism?', 'The idea that the UK PM has become more like a president, with personal mandates and dominance.', 16),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'Why did Thatcher fall in 1990?', 'Loss of Cabinet support, the poll tax, and divisions over Europe led to a leadership challenge.', 17),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'Why did Theresa May resign in 2019?', 'She failed to pass her Brexit withdrawal agreement and lost the support of her party.', 18),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'Why did Boris Johnson resign in 2022?', 'Scandals such as Partygate and the Pincher affair led to mass ministerial resignations.', 19),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'Why was Liz Truss''s premiership so short?', 'Her 2022 mini-budget caused market turmoil, destroying her authority; she resigned after 49 days.', 20),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What is the role of the Cabinet Office?', 'It supports the PM and Cabinet and coordinates government policy.', 21),
  ('Politics', 'AQA', 'alevel', '1.3', 'Prime Minister and Cabinet', 'What is the royal prerogative?', 'Powers historically held by the monarch, now mostly exercised by ministers, e.g. treaty-making and deploying the armed forces.', 22),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What is the UK Supreme Court''s role?', 'The final court of appeal for civil cases in the UK and criminal cases in England, Wales and Northern Ireland; it also hears devolution cases.', 1),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'When did the UK Supreme Court begin work?', 'October 2009, replacing the Appellate Committee of the House of Lords.', 2),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'How many justices sit on the UK Supreme Court?', 'Twelve justices, led by the President of the Supreme Court.', 3),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What is judicial neutrality?', 'Judges should decide cases impartially, without political bias or personal preferences.', 4),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What is security of tenure for judges?', 'Senior judges can only be removed by a vote of both Houses of Parliament, protecting their independence.', 5),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'How are judges'' salaries protected?', 'They are paid from the Consolidated Fund, so Parliament doesn''t vote on them each year.', 6),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What is the Judicial Appointments Commission?', 'An independent body that selects judges in England and Wales based on merit.', 7),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'Why is the UK judiciary criticised as unrepresentative?', 'Senior judges are disproportionately white, male, privately educated and Oxbridge graduates.', 8),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What is the principle of ultra vires?', 'A public body acting beyond its legal powers; the courts can rule such action unlawful.', 9),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What is judicial review based on irrationality?', 'A decision so unreasonable that no reasonable authority could have made it (Wednesbury unreasonableness).', 10),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What is judicial review based on procedural impropriety?', 'A decision made without following the correct procedures or principles of fairness.', 11),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What is Section 3 of the Human Rights Act?', 'Courts must interpret legislation compatibly with Convention rights "so far as it is possible to do so".', 12),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What is Section 4 of the Human Rights Act?', 'Allows higher courts to issue a declaration of incompatibility if legislation can''t be read compatibly.', 13),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'Give an example of a declaration of incompatibility being acted on.', 'After the Belmarsh ruling (2004), Parliament replaced indefinite detention with control orders in 2005.', 14),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What is the Lord Chancellor''s role after 2005?', 'A Cabinet minister (Justice Secretary) who must uphold judicial independence but no longer sits as a judge or heads the judiciary.', 15),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'Who heads the judiciary of England and Wales?', 'The Lady/Lord Chief Justice, since the Constitutional Reform Act 2005.', 16),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What was the significance of R (UNISON) v Lord Chancellor (2017)?', 'The Supreme Court ruled employment tribunal fees unlawful because they prevented access to justice.', 17),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What was the significance of the Rwanda case (2023)?', 'The Supreme Court ruled the Rwanda asylum policy unlawful due to the risk of refoulement.', 18),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What was the Safety of Rwanda Act 2024?', 'Parliament declared Rwanda a safe country by statute, overriding the Supreme Court''s factual finding, showing parliamentary sovereignty.', 19),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What is judicial activism in the UK?', 'Judges taking a broad interpretation of their powers to check government, e.g. in the Miller cases.', 20),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'Why do critics call UK judges too political?', 'High-profile rulings on Brexit, asylum and prorogation led some to claim judges were interfering in politics.', 21),
  ('Politics', 'AQA', 'alevel', '1.4', 'The Judiciary', 'What is the counter-argument to judges being ''too political''?', 'Judges only apply the law; political cases reach them because governments act unlawfully or Parliament gives them powers.', 22),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What is devolution?', 'The transfer of power from central government to subnational bodies, without giving up sovereignty.', 1),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'When did devolution happen in Scotland and Wales?', 'Referendums in 1997 led to the Scottish Parliament and Welsh Assembly (now Senedd) opening in 1999.', 2),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What powers does the Scottish Parliament have?', 'Primary legislative power over devolved matters such as health, education, justice, and some taxation and welfare powers.', 3),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What are reserved powers?', 'Powers kept by Westminster, e.g. defence, foreign affairs and the constitution.', 4),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What was the Scotland Act 2016?', 'It gave the Scottish Parliament more tax and welfare powers and declared it a permanent part of the UK constitution.', 5),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What was the Wales Act 2017?', 'It moved Wales to a reserved powers model, similar to Scotland.', 6),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'When did the Welsh Assembly become the Senedd?', '2020, when it was renamed Senedd Cymru (Welsh Parliament).', 7),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What was the Good Friday Agreement (1998)?', 'A peace agreement establishing power-sharing in Northern Ireland, with cross-border cooperation.', 8),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What is power-sharing in Northern Ireland?', 'The executive must include both unionist and nationalist parties, with a First Minister and deputy First Minister of equal status.', 9),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'Why has the Northern Ireland Assembly been suspended?', 'Power-sharing collapses when a major party withdraws, e.g. 2017–2020 and 2022–2024.', 10),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What was the 2014 Scottish independence referendum result?', '55% voted No to independence, on a turnout of about 85%.', 11),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What was the Supreme Court''s 2022 ruling on a second independence referendum?', 'The Scottish Parliament can''t legislate for an independence referendum without Westminster''s consent.', 12),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What is English regional devolution?', 'Transfer of powers to combined authorities with elected mayors, e.g. Greater Manchester.', 13),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'When was the London Mayor created?', '2000, following a 1998 referendum.', 14),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What happened to the North East regional assembly proposal?', 'It was rejected in a 2004 referendum by 78% to 22%.', 15),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What is asymmetric devolution?', 'Different parts of the UK have different levels of devolved power.', 16),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What is the English question?', 'The debate over how England should be governed, given it lacks its own parliament.', 17),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'Why is devolution not federalism?', 'Westminster remains sovereign and can in theory amend or abolish devolved institutions.', 18),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'Why is devolution described as entrenched in practice?', 'Devolution was approved by referendums and is politically very difficult to reverse.', 19),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What was the UK Internal Market Act 2020?', 'A law ensuring goods and services can move freely across the UK, criticised for limiting devolved powers.', 20),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'What is the Section 35 order and when was it first used?', 'A power allowing the UK government to block Scottish legislation; first used in 2023 against the Gender Recognition Reform Bill.', 21),
  ('Politics', 'AQA', 'alevel', '1.5', 'Devolution', 'Has devolution strengthened or weakened the Union?', 'It may have reduced support for independence by meeting demands, but has also given nationalists a platform.', 22),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What is democracy?', 'A system of government in which power rests with the people, who exercise it directly or through elected representatives.', 1),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What is direct democracy?', 'Citizens make decisions themselves, e.g. through referendums, rather than electing representatives.', 2),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What is representative democracy?', 'Citizens elect representatives to make decisions on their behalf, and hold them accountable at elections.', 3),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'Give two advantages of direct democracy.', 'It gives decisions strong legitimacy and increases political participation and education.', 4),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'Give two disadvantages of direct democracy.', 'Complex issues are oversimplified, and it risks the tyranny of the majority and low turnout.', 5),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What is pluralist democracy?', 'A democracy where power is dispersed among many competing groups, such as parties and pressure groups.', 6),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What is the franchise?', 'The right to vote in elections.', 7),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'When did women gain equal voting rights with men in the UK?', '1928 (Representation of the People (Equal Franchise) Act); some women over 30 had gained the vote in 1918.', 8),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'When was the voting age lowered to 18 in the UK?', '1969, by the Representation of the People Act.', 9),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What are the arguments for lowering the voting age to 16?', '16-year-olds pay taxes, can work and marry; it may increase engagement; and 16-year-olds already vote in Scottish and Welsh elections.', 10),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What are the arguments against votes at 16?', 'Lack of maturity and experience, low turnout among young voters, and inconsistency with other age limits.', 11),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What is a pressure group?', 'An organisation that seeks to influence government policy without seeking election to office.', 12),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What is an insider group?', 'A pressure group with close links to and regular access to government, e.g. the BMA.', 13),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What is an outsider group?', 'A pressure group without access to government, which uses public campaigns and direct action, e.g. Extinction Rebellion.', 14),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What is a think tank?', 'An organisation that researches and develops policy ideas to influence government, e.g. the Institute for Fiscal Studies.', 15),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What is a lobbyist?', 'A professional paid to influence politicians and policy on behalf of clients.', 16),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What is e-democracy?', 'The use of digital technology in democratic processes, e.g. online petitions and social media campaigns.', 17),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What happens to a UK Parliament e-petition with 100,000 signatures?', 'It is considered for debate in Parliament by the Petitions Committee.', 18),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What are rights in the UK?', 'Entitlements protected by law, such as freedom of speech, association and a fair trial, largely set out in the Human Rights Act 1998.', 19),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What is the role of the Equality Act 2010?', 'It consolidated anti-discrimination law, protecting nine characteristics including age, race, sex and disability.', 20),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'How have civil liberties been in conflict with security?', 'E.g. anti-terror laws allowing detention without charge and surveillance powers (Investigatory Powers Act 2016).', 21),
  ('Politics', 'AQA', 'alevel', '1.6', 'Democracy and Participation', 'What is the role of pressure groups in promoting rights?', 'Groups like Liberty and Amnesty campaign, bring legal cases, and raise awareness to protect rights.', 22),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What is First Past the Post?', 'A plurality system: the candidate with the most votes in each constituency wins, regardless of whether they have a majority.', 1),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What are the advantages of FPTP?', 'Simple, quick results, strong single-party governments, and a clear MP–constituency link.', 2),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What are the disadvantages of FPTP?', 'Disproportionate results, wasted votes, safe seats, and tactical voting.', 3),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What is a safe seat?', 'A constituency where one party has a large majority and is very likely to win.', 4),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What is a marginal seat?', 'A constituency where the winning party has a small majority, so it could change hands.', 5),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What is tactical voting?', 'Voting for a less preferred candidate to prevent a disliked candidate from winning.', 6),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What is a wasted vote?', 'A vote that doesn''t contribute to electing a candidate, e.g. votes for losing candidates or surplus votes for winners.', 7),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What is the Supplementary Vote?', 'Voters mark first and second preferences; if no candidate gets 50%, the top two remain and second preferences are counted. It was used for mayors and PCCs until 2023.', 8),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'Why was the Supplementary Vote replaced in England?', 'The Elections Act 2022 switched mayoral and PCC elections to FPTP.', 9),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What is STV?', 'The Single Transferable Vote: voters rank candidates in multi-member constituencies, and candidates reaching a quota are elected, with surplus and eliminated votes transferred.', 10),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'Where is AMS used in the UK?', 'The Scottish Parliament, the Senedd (until 2026) and the London Assembly.', 11),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'How is the Senedd electoral system changing?', 'From 2026 it uses a closed list PR system with larger multi-member constituencies and 96 members.', 12),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What are the advantages of AMS?', 'More proportional than FPTP while keeping constituency MPs, and voters get two votes.', 13),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What are the disadvantages of AMS?', 'Two classes of representative, closed party lists give parties control, and it often produces coalitions.', 14),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What is the D''Hondt formula?', 'A method of allocating list seats: votes ÷ (seats already won + 1), used in AMS regional lists.', 15),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What is a coalition government?', 'A government formed by two or more parties, usually when no party has a majority.', 16),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What is a referendum?', 'A vote by the electorate on a single issue.', 17),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'Give two examples of UK-wide referendums.', 'The 1975 EEC membership referendum, the 2011 AV referendum and the 2016 EU referendum.', 18),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What was the result of the 2016 EU referendum?', 'Leave won 51.9% to 48.1% on a 72.2% turnout.', 19),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What are the arguments for referendums?', 'They give legitimacy to major constitutional decisions and increase participation.', 20),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'What are the arguments against referendums?', 'Complex issues are oversimplified, turnout can be low, and they undermine representative democracy.', 21),
  ('Politics', 'AQA', 'alevel', '1.7', 'Elections and Referendums', 'Are UK referendums legally binding?', 'No; due to parliamentary sovereignty they are advisory, although politically very hard to ignore.', 22),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What is a political party?', 'An organised group of people with shared ideas who seek to win elections and form a government.', 1),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What are the functions of political parties?', 'Representation, policy formulation, recruitment of leaders, political participation and forming government.', 2),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'How are UK parties funded?', 'Membership fees, donations from individuals, businesses and trade unions, and state funding such as Short money.', 3),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What is Cranborne money?', 'State funding for opposition parties in the House of Lords.', 4),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What are the arguments for state funding of parties?', 'It reduces the influence of wealthy donors, creates a level playing field, and allows parties to focus on policy.', 5),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What are the arguments against state funding of parties?', 'Taxpayers fund parties they oppose, it may favour established parties, and parties could lose touch with members.', 6),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What is the role of the Electoral Commission?', 'It regulates party finance and elections, including donations and spending limits.', 7),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What were the key features of Thatcherism?', 'Free markets, privatisation, reducing trade union power, low taxes, and a strong state on law and order.', 8),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What was New Labour?', 'The rebranding of Labour under Blair: the Third Way, accepting markets while investing in public services.', 9),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What are the key ideas of the Liberal Democrats?', 'Constitutional reform (including PR), civil liberties, pro-Europeanism, and environmental protection.', 10),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What is a minor party?', 'A party with limited representation in Parliament, e.g. the Greens or Reform UK.', 11),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What is a nationalist party?', 'A party seeking greater autonomy or independence for a nation, e.g. the SNP or Plaid Cymru.', 12),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What is a multi-party system?', 'A system where more than two parties have a realistic chance of forming or influencing government.', 13),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What is a dominant-party system?', 'A system where one party wins power repeatedly for a long period.', 14),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'How did the 2010 election affect the party system?', 'It produced a hung parliament and a Conservative–Liberal Democrat coalition, the first since 1945.', 15),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What was the result of the 2024 general election?', 'Labour won a large majority (411 seats) on about 34% of the vote; the Conservatives fell to 121 seats; the Lib Dems won 72.', 16),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'How did Reform UK perform in 2024?', 'It won about 14% of the vote but only 5 seats, showing how FPTP penalises parties with evenly spread support.', 17),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What is party leadership selection in the Conservative Party?', 'MPs narrow the candidates to two, then members vote in a ballot.', 18),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What is party leadership selection in the Labour Party?', 'Candidates need nominations from MPs (and affiliates or CLPs), then members and registered supporters vote using a preferential system.', 19),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What is the impact of party leaders on electoral success?', 'Leaders shape party image and media coverage; popular leaders (e.g. Blair in 1997) help, unpopular ones hinder.', 20),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What is a manifesto?', 'A document setting out a party''s policies and promises before an election.', 21),
  ('Politics', 'AQA', 'alevel', '1.8', 'Political Parties', 'What is the Salisbury Convention?', 'The Lords do not block legislation promised in the governing party''s manifesto at second reading.', 22),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What is a pressure group?', 'An organisation that seeks to influence public policy without standing for election.', 1),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'Give an example of a sectional group.', 'The British Medical Association, which represents doctors.', 2),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'Give an example of a promotional group.', 'Greenpeace, which campaigns on environmental issues.', 3),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What methods do insider groups use?', 'Direct contact with ministers and civil servants, consultation, and giving evidence to committees.', 4),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What methods do outsider groups use?', 'Protests, demonstrations, direct action and media campaigns.', 5),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What is direct action?', 'Taking action to achieve goals directly, e.g. blockades, occupations and civil disobedience.', 6),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'Give an example of a successful pressure group campaign.', 'Marcus Rashford''s 2020 campaign forced the government to extend free school meals over holidays.', 7),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'Give an example of an unsuccessful pressure group campaign.', 'The 2003 Stop the War protests failed to prevent the Iraq War despite very large demonstrations.', 8),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What is a think tank?', 'A research organisation developing policy ideas, e.g. the Institute of Economic Affairs or IPPR.', 9),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What is lobbying?', 'Attempting to influence politicians and officials, often by professional firms on behalf of clients.', 10),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What is the concern about lobbying?', 'It can give wealthy interests unfair access and influence, e.g. the Greensill scandal (2021).', 11),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What was the Greensill scandal?', 'David Cameron lobbied ministers by text on behalf of Greensill Capital, raising concerns about access.', 12),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What factors help a pressure group succeed?', 'Insider status, resources, public support, expertise, and alignment with government priorities.', 13),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What is the role of social media in pressure group activity?', 'It enables rapid mobilisation, cheap campaigns, and online petitions, although "clicktivism" may be shallow.', 14),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What is clicktivism?', 'Low-effort online activism such as signing e-petitions or sharing posts.', 15),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What is corporate power?', 'The influence of businesses on government through lobbying, funding, and their economic importance.', 16),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'Why are trade unions less influential than in the 1970s?', 'Membership fell, laws restricted strikes, and governments stopped involving them in policymaking (end of corporatism).', 17),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What is corporatism?', 'A system where government works closely with business and unions to make policy, common in the 1960s and 70s.', 18),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'How do pressure groups enhance democracy?', 'They increase participation, represent minorities, provide expertise and hold government to account.', 19),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'How do pressure groups undermine democracy?', 'Unequal resources give wealthy groups more influence, and they are often undemocratic internally.', 20),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What was the Public Order Act 2023?', 'A law creating new offences for protest tactics such as "locking on", criticised for restricting protest rights.', 21),
  ('Politics', 'AQA', 'alevel', '1.9', 'Pressure Groups', 'What is the role of legal challenges for pressure groups?', 'Groups use judicial review to challenge government decisions, e.g. environmental groups challenging climate policy.', 22),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What is the European Union?', 'A political and economic union of European states that pool sovereignty in some areas.', 1),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'When did the UK join the EEC?', '1 January 1973, confirmed by the 1975 referendum.', 2),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'When did the UK leave the EU?', '31 January 2020, with the transition period ending on 31 December 2020.', 3),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What is the European Commission?', 'The EU''s executive, proposing laws and enforcing EU treaties.', 4),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What is the European Parliament?', 'The EU''s directly elected legislature, sharing legislative power with the Council.', 5),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What is the Council of the EU?', 'The body where national ministers meet to make EU laws.', 6),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What is the European Council?', 'The meeting of EU heads of government that sets the EU''s political direction.', 7),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What is qualified majority voting?', 'A voting system in the Council where decisions need the support of 55% of states representing 65% of the EU population.', 8),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What is the Court of Justice of the European Union?', 'The court that interprets EU law and ensures it is applied equally in member states.', 9),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What was the European Communities Act 1972?', 'The Act that incorporated EU law into UK law, giving it supremacy while the UK was a member.', 10),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What is Article 50?', 'The Lisbon Treaty article setting out how a member state can leave the EU.', 11),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What was the Withdrawal Agreement?', 'The treaty setting the terms of the UK''s exit, including citizens'' rights, the financial settlement and the Northern Ireland Protocol.', 12),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What was the Northern Ireland Protocol?', 'An arrangement keeping Northern Ireland aligned with some EU rules to avoid a hard border in Ireland.', 13),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What was the Windsor Framework (2023)?', 'A UK–EU agreement revising the Northern Ireland Protocol, reducing checks on goods moving from Great Britain.', 14),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What was the Trade and Cooperation Agreement?', 'The 2020 UK–EU agreement on trade and cooperation after Brexit, providing tariff-free trade in goods.', 15),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What is retained EU law?', 'EU law kept in UK law after Brexit, which Parliament can amend or repeal.', 16),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What did the Retained EU Law (Revocation and Reform) Act 2023 do?', 'It ended the special status of EU law in the UK and allowed ministers to amend or revoke it.', 17),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'Why did Leave win the 2016 referendum?', 'Concerns about immigration, sovereignty ("Take back control") and dissatisfaction with the political establishment.', 18),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What was the impact of Brexit on parliamentary sovereignty?', 'Legal sovereignty returned fully to Parliament, although the process caused major conflict between Parliament and the executive.', 19),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'How did Brexit affect the UK party system?', 'It split both main parties, led to the rise of the Brexit Party, and reshaped voting in 2019.', 20),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'How did Brexit affect Scotland?', 'Scotland voted 62% Remain, strengthening demands for a second independence referendum.', 21),
  ('Politics', 'AQA', 'alevel', '1.10', 'The European Union', 'What was the Benn Act (2019)?', 'A law requiring the PM to seek a Brexit extension if no deal was agreed, passed by Parliament against the government''s wishes.', 22),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is a codified constitution?', 'A constitution written in a single document, like the US Constitution.', 1),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is an entrenched constitution?', 'A constitution protected by special amendment procedures, making it hard to change.', 2),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What are the Articles of the US Constitution?', 'Article I: Congress; Article II: the President; Article III: the judiciary; others cover states, amendment and supremacy.', 3),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is the Bill of Rights?', 'The first ten amendments to the US Constitution, protecting individual rights.', 4),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is the First Amendment?', 'Freedom of religion, speech, press, assembly and petition.', 5),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is the Second Amendment?', 'The right to keep and bear arms.', 6),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is the Fourteenth Amendment?', 'It guarantees equal protection of the laws and due process to all citizens.', 7),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'How is the US Constitution amended?', 'Proposed by two-thirds of both houses of Congress (or a convention called by two-thirds of states), and ratified by three-quarters of the states.', 8),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'How many amendments have there been?', '27, the last being ratified in 1992.', 9),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is the separation of powers in the US?', 'Legislative power with Congress, executive power with the President, and judicial power with the courts.', 10),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is federalism?', 'Power is shared between the federal government and the states.', 11),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is dual federalism?', 'Federal and state governments operate in separate spheres (the "layer cake" model).', 12),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is cooperative federalism?', 'Federal and state governments work together, e.g. through grants (the "marble cake" model).', 13),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is new federalism?', 'Returning power to the states, associated with Nixon and Reagan.', 14),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is the Commerce Clause?', 'It gives Congress power to regulate interstate commerce, used to expand federal power.', 15),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is the Necessary and Proper Clause?', 'It gives Congress power to make laws needed to carry out its enumerated powers.', 16),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is the Supremacy Clause?', 'Federal law takes precedence over state law.', 17),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What are the strengths of the US Constitution?', 'Protects rights, limits government, is flexible through interpretation, and has lasted over 230 years.', 18),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What are the weaknesses of the US Constitution?', 'Hard to amend, outdated provisions (e.g. the Second Amendment debate), and the Electoral College.', 19),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is the role of the states?', 'States control many areas, e.g. education, criminal law and elections.', 20),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'What is the significance of the Tenth Amendment?', 'Powers not given to the federal government are reserved to the states or the people.', 21),
  ('Politics', 'AQA', 'alevel', '2.1', 'The US Constitution and Federalism', 'How has federal power grown?', 'Through the New Deal, the Great Society, the Commerce Clause, and responses to crises such as 9/11.', 22),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is the House of Representatives?', 'The lower chamber of Congress, with 435 members elected every two years based on population.', 1),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is the Senate?', 'The upper chamber, with 100 members (two per state) elected for six years.', 2),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What are the powers of Congress?', 'Legislation, taxation, declaring war, confirming appointments (Senate), ratifying treaties (Senate) and impeachment.', 3),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is the power of the purse?', 'Congress controls taxation and spending.', 4),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is the legislative process in the US?', 'Introduction, committee stage, floor debate and vote in both houses, a conference committee if needed, and presidential approval or veto.', 5),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is a presidential veto?', 'The President''s rejection of a bill, which can be overridden by two-thirds of both houses.', 6),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is a pocket veto?', 'When the President doesn''t sign a bill within 10 days and Congress has adjourned, so it fails.', 7),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is the role of the Speaker of the House?', 'The presiding officer and leader of the majority party, controlling the legislative agenda.', 8),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is the role of the Senate Majority Leader?', 'The leader of the majority party in the Senate, controlling the floor agenda.', 9),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is a standing committee?', 'A permanent committee that scrutinises legislation and oversees policy areas.', 10),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is the House Rules Committee?', 'It sets the terms of debate for bills in the House.', 11),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is the role of Congress in oversight?', 'Investigating and scrutinising the executive through hearings and investigations.', 12),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is the confirmation power of the Senate?', 'The Senate must approve presidential appointments, including Supreme Court justices and Cabinet members.', 13),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is the treaty ratification power?', 'Treaties require approval by two-thirds of the Senate.', 14),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is impeachment?', 'The House can impeach (charge) federal officials; the Senate tries them, and removal requires a two-thirds vote.', 15),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'How many times has a President been impeached?', 'Three presidents, four impeachments: Andrew Johnson (1868), Clinton (1998) and Trump (2019 and 2021). None was removed by the Senate.', 16),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is partisanship in Congress?', 'Members voting along party lines; it has increased greatly in recent decades.', 17),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is gridlock?', 'When Congress and the President fail to pass legislation because of divided government or partisanship.', 18),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is divided government?', 'When one party controls the presidency and the other controls one or both houses of Congress.', 19),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is representation in Congress?', 'Members represent their constituents, parties and interest groups.', 20),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is pork-barrel politics?', 'Spending targeted at a member''s district to gain support.', 21),
  ('Politics', 'AQA', 'alevel', '2.2', 'Congress', 'What is the significance of incumbency?', 'Incumbents have very high re-election rates due to name recognition, funding and constituency service.', 22),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What are the formal powers of the President?', 'Commander-in-chief, proposing legislation, veto, appointments, treaties, pardons and executing laws.', 1),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What are the informal powers of the President?', 'Persuasion, the electoral mandate, the bully pulpit, and executive orders.', 2),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is the power to persuade?', 'Neustadt''s argument that the President''s real power lies in persuading others.', 3),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is an executive order?', 'A directive issued by the President to manage the federal government, without congressional approval.', 4),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is a signing statement?', 'A statement issued by the President when signing a bill, which may interpret or challenge parts of it.', 5),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is the Executive Office of the President?', 'The agencies that support the President, including the White House Office and the Office of Management and Budget.', 6),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is the Cabinet in the US?', 'The heads of the executive departments, who advise the President but have no collective responsibility.', 7),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is the bully pulpit?', 'The President''s platform to speak directly to the public and influence opinion.', 8),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is the imperial presidency?', 'Schlesinger''s idea that the President has become too powerful, especially in foreign policy.', 9),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is the imperilled presidency?', 'The idea that the President is too weak because of constraints from Congress, courts and media.', 10),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What are the constraints on the President?', 'Congress, the Supreme Court, the Constitution, federalism, public opinion and the media.', 11),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is the War Powers Resolution 1973?', 'It requires the President to notify Congress within 48 hours of deploying troops and limits deployments to 60 days without approval.', 12),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is the role of the Vice President?', 'President of the Senate with a tie-breaking vote, and first in line to succeed the President.', 13),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is the 25th Amendment?', 'It sets out procedures for presidential succession and disability.', 14),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is a lame duck President?', 'A President in the final period of office, often with reduced power.', 15),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is the honeymoon period?', 'The early period of a presidency when the President has high approval and can achieve more.', 16),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is the role of the President in foreign policy?', 'Commander-in-chief, negotiating treaties, appointing ambassadors, and leading diplomacy.', 17),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is executive privilege?', 'The President''s claim to withhold information from Congress and the courts, limited by US v Nixon (1974).', 18),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is the significance of US v Nixon (1974)?', 'The Supreme Court ruled the President must hand over the Watergate tapes, limiting executive privilege.', 19),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is the unitary executive theory?', 'The view that the President has complete control over the executive branch.', 20),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is a presidential mandate?', 'The authority to carry out policies based on winning an election.', 21),
  ('Politics', 'AQA', 'alevel', '2.3', 'The Presidency', 'What is presidential approval rating?', 'A measure of public support for the President, which affects their power.', 22),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What is judicial review in the US?', 'The power of courts to declare laws and executive actions unconstitutional.', 1),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What is the Supreme Court''s composition?', 'Nine justices appointed for life by the President and confirmed by the Senate.', 2),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What is judicial activism?', 'When judges actively interpret the Constitution to shape policy.', 3),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What is judicial restraint?', 'When judges defer to elected branches and follow precedent.', 4),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What is originalism?', 'Interpreting the Constitution according to its original meaning.', 5),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What is the living constitution?', 'Interpreting the Constitution in light of current values.', 6),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What is stare decisis?', 'Following precedent in judicial decisions.', 7),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What was Brown v Board of Education (1954)?', 'It ruled racial segregation in public schools unconstitutional.', 8),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What was Roe v Wade (1973)?', 'It established a constitutional right to abortion.', 9),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What was Dobbs v Jackson (2022)?', 'It overturned Roe v Wade, returning abortion regulation to the states.', 10),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What was Obergefell v Hodges (2015)?', 'It legalised same-sex marriage nationwide.', 11),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What was DC v Heller (2008)?', 'It ruled the Second Amendment protects an individual right to own firearms.', 12),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What was Students for Fair Admissions v Harvard (2023)?', 'It ruled race-conscious affirmative action in college admissions unconstitutional.', 13),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What is a swing justice?', 'A justice whose vote often decides close cases, e.g. Anthony Kennedy.', 14),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What is the politicisation of the Supreme Court?', 'The perception that justices vote along ideological lines and that appointments are highly partisan.', 15),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What was the controversy over the Garland nomination (2016)?', 'The Republican Senate refused to hold hearings for Obama''s nominee, Merrick Garland.', 16),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What is the current ideological balance of the Supreme Court?', 'A 6–3 conservative majority following Trump''s three appointments.', 17),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What is the civil rights movement?', 'The struggle for equal rights for African Americans, especially in the 1950s and 60s.', 18),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What was the Civil Rights Act 1964?', 'It banned discrimination based on race, colour, religion, sex or national origin.', 19),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What was the Voting Rights Act 1965?', 'It outlawed discriminatory voting practices such as literacy tests.', 20),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What was Shelby County v Holder (2013)?', 'It struck down a key part of the Voting Rights Act requiring federal pre-clearance for some states.', 21),
  ('Politics', 'AQA', 'alevel', '2.4', 'The Supreme Court and the Judicial Branch', 'What is affirmative action?', 'Policies giving preferential treatment to disadvantaged groups to address past discrimination.', 22),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is the presidential election process?', 'Invisible primary, primaries and caucuses, national conventions, the general election campaign, and the Electoral College vote.', 1),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is the Electoral College?', '538 electors allocated to states based on congressional representation; a candidate needs 270 to win.', 2),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is winner-takes-all?', 'In most states, the candidate with the most votes wins all the state''s electoral votes.', 3),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'Which states don''t use winner-takes-all?', 'Maine and Nebraska allocate some electoral votes by congressional district.', 4),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is a swing state?', 'A state where either party could win, e.g. Pennsylvania, Michigan and Wisconsin.', 5),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is a national convention?', 'A party meeting that formally nominates its presidential candidate and adopts a platform.', 6),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is the significance of Super Tuesday?', 'The day when many states hold primaries, often decisive in the nomination race.', 7),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is campaign finance?', 'The funding of election campaigns, regulated by law.', 8),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is a Super PAC?', 'A political action committee that can raise and spend unlimited amounts, but can''t coordinate directly with campaigns.', 9),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is soft money?', 'Money donated to parties for general activities rather than specific candidates, restricted by the Bipartisan Campaign Reform Act 2002.', 10),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is the role of interest groups in the US?', 'They lobby Congress and the executive, fund campaigns and bring legal cases.', 11),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is the NRA?', 'The National Rifle Association, an influential interest group defending gun rights.', 12),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is lobbying?', 'Attempting to influence legislators and officials on behalf of interest groups.', 13),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is the revolving door?', 'Movement of people between government and lobbying roles.', 14),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What are the two main parties in the US?', 'The Democrats (liberal) and the Republicans (conservative).', 15),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is party polarisation?', 'Parties moving further apart ideologically, with fewer moderates.', 16),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is the role of third parties?', 'They can influence debate and act as spoilers, e.g. Ralph Nader in 2000.', 17),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is voter turnout in US elections?', 'Relatively low compared with other democracies, especially in midterms.', 18),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is the midterm election?', 'Elections held halfway through a presidential term, for all House seats and a third of the Senate.', 19),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What factors influence voting in the US?', 'Race, religion, gender, education, age, region and the economy.', 20),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is voter ID laws'' impact?', 'Critics argue they suppress minority turnout; supporters say they prevent fraud.', 21),
  ('Politics', 'AQA', 'alevel', '2.5', 'Elections and Direct Democracy', 'What is the significance of the 2020 election?', 'Biden won, and Trump''s refusal to accept the result led to the 6 January 2021 Capitol attack.', 22),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What are the two main US parties?', 'The Democrats and the Republicans.', 1),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What are the core Democratic policies?', 'Government action on healthcare, climate change, social programmes, abortion rights and gun control.', 2),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What are the core Republican policies?', 'Lower taxes, smaller government, gun rights, restrictions on abortion and tougher immigration policies.', 3),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'Why are US parties described as decentralised?', 'Power lies with state and local parties and candidates rather than a central national organisation.', 4),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What is the role of the Democratic National Committee (DNC)?', 'It coordinates national strategy, fundraising and the national convention.', 5),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What is a big tent party?', 'A party containing a wide range of views, as US parties historically did.', 6),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What are the factions in the Democratic Party?', 'Progressives (e.g. Bernie Sanders, AOC) and moderates or centrists (e.g. Joe Biden).', 7),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What are the factions in the Republican Party?', 'The MAGA/Trump-populist wing, traditional conservatives, the religious right and libertarians.', 8),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What is the Tea Party movement?', 'A conservative movement from 2009 opposing high taxes and government spending, which pushed Republicans to the right.', 9),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What is the MAGA movement?', 'A populist nationalist movement associated with Donald Trump, emphasising immigration restriction and "America First".', 10),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What is the Freedom Caucus?', 'A group of hardline conservative Republicans in the House of Representatives.', 11),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What is the Progressive Caucus?', 'A group of left-wing Democrats in Congress.', 12),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'Why do third parties struggle in the US?', 'FPTP and winner-takes-all, ballot access rules, lack of funding, and the main parties absorbing their ideas.', 13),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'Give an example of a significant third-party candidate.', 'Ross Perot won 19% of the popular vote in 1992 but no Electoral College votes.', 14),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What is the party realignment of the South?', 'After the 1960s civil rights legislation, white Southern voters moved from the Democrats to the Republicans.', 15),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What are the key Democratic voting groups?', 'African Americans, urban voters, college-educated women, young voters and many Hispanic voters.', 16),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What are the key Republican voting groups?', 'White evangelicals, rural voters, non-college white voters and older voters.', 17),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What is party unity voting?', 'When a majority of one party votes against a majority of the other; it has increased sharply.', 18),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What is negative partisanship?', 'Voters are motivated more by dislike of the other party than support for their own.', 19),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What is the effect of primaries on parties?', 'They weaken party leaders'' control over candidates and can push candidates to ideological extremes.', 20),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'What is the party platform?', 'A statement of the party''s policy positions, adopted at the national convention.', 21),
  ('Politics', 'AQA', 'alevel', '2.6', 'US Political Parties', 'Is the US a two-party system?', 'Yes: Democrats and Republicans dominate at all levels, and third parties rarely win seats.', 22),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What are the main types of US pressure groups?', 'Business groups, professional groups, labour unions, single-issue groups, ideological groups and public interest groups.', 1),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'Give an example of a single-issue group in the US.', 'The NRA (gun rights) or Planned Parenthood (reproductive rights).', 2),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'Give an example of a professional group.', 'The American Medical Association.', 3),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'Give an example of a business group.', 'The US Chamber of Commerce.', 4),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'Give an example of an ideological group.', 'The American Civil Liberties Union (ACLU) or the Heritage Foundation.', 5),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What methods do US pressure groups use?', 'Lobbying, campaign donations (via PACs), grassroots campaigns, litigation and amicus briefs.', 6),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What is an amicus curiae brief?', 'A "friend of the court" brief submitted by an interest group to influence a Supreme Court case.', 7),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What is electioneering?', 'Groups supporting or opposing candidates through donations, endorsements and advertising.', 8),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What is grassroots lobbying?', 'Encouraging members of the public to contact their representatives.', 9),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What is astroturfing?', 'Campaigns funded by corporations or interests that are made to look like grassroots movements.', 10),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What is AIPAC?', 'The American Israel Public Affairs Committee, a highly influential foreign-policy lobbying group.', 11),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What is the influence of the NRA?', 'Through lobbying, member mobilisation and campaign spending it has limited federal gun control.', 12),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'Why has the NRA''s influence declined recently?', 'Financial scandals, internal disputes and falling income, and the Bipartisan Safer Communities Act 2022.', 13),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What is Black Lives Matter?', 'A social movement campaigning against police violence and systemic racism.', 14),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What is the #MeToo movement?', 'A movement against sexual harassment and assault, which led to legal and cultural changes.', 15),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What are the arguments that US pressure groups enhance democracy?', 'They represent diverse interests, increase participation, and provide expertise and access.', 16),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What are the arguments that US pressure groups undermine democracy?', 'Wealthy groups dominate, money buys access, and elected officials may be captured.', 17),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What is regulatory capture?', 'When regulators act in the interests of the industry they regulate.', 18),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What is the Lobbying Disclosure Act 1995?', 'A law requiring lobbyists to register and disclose their activities.', 19),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What is pluralism in the US?', 'The view that power is dispersed among many competing groups.', 20),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'What is elitism in the US?', 'The view that power is concentrated in a small elite of wealthy and powerful groups.', 21),
  ('Politics', 'AQA', 'alevel', '2.7', 'US Pressure Groups', 'Why do US pressure groups target the courts?', 'Court rulings can achieve policy change when Congress is gridlocked, and the Supreme Court can set national policy.', 22),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What is a civil right?', 'A right protecting individuals from discrimination and ensuring equal treatment by the state.', 1),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What is a civil liberty?', 'A freedom protected from government interference, e.g. free speech.', 2),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What was the Emancipation Proclamation (1863)?', 'Lincoln''s order declaring enslaved people in Confederate states free.', 3),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What was the Thirteenth Amendment (1865)?', 'It abolished slavery.', 4),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What was the Fifteenth Amendment (1870)?', 'It prohibited denying the vote based on race.', 5),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What were Jim Crow laws?', 'State and local laws enforcing racial segregation in the South.', 6),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What was the Montgomery Bus Boycott?', 'A 1955–56 protest against bus segregation, sparked by Rosa Parks, leading to a Supreme Court ruling against segregated buses.', 7),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What was the role of Martin Luther King Jr.?', 'A leader of the civil rights movement advocating non-violent protest.', 8),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What was the March on Washington (1963)?', 'A mass demonstration for civil rights where King gave his "I Have a Dream" speech.', 9),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What was the Nineteenth Amendment (1920)?', 'It gave women the right to vote.', 10),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What was the Equal Rights Amendment?', 'A proposed amendment guaranteeing equal rights regardless of sex, which failed to be ratified by enough states.', 11),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What was Loving v Virginia (1967)?', 'It struck down laws banning interracial marriage.', 12),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What was Regents of University of California v Bakke (1978)?', 'It banned racial quotas but allowed race as one factor in admissions.', 13),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What was Grutter v Bollinger (2003)?', 'It upheld the use of race as one factor in university admissions.', 14),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What is the Americans with Disabilities Act (1990)?', 'It banned discrimination against people with disabilities.', 15),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What was Bostock v Clayton County (2020)?', 'It ruled the Civil Rights Act protects gay and transgender employees from discrimination.', 16),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What is voter suppression?', 'Tactics that make it harder for certain groups to vote, e.g. strict ID laws, purges of voter rolls and closing polling stations.', 17),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What is immigration as a civil rights issue?', 'Debates over the rights of undocumented immigrants, DACA recipients and border policies.', 18),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What is DACA?', 'Deferred Action for Childhood Arrivals: an Obama-era policy protecting undocumented people brought to the US as children from deportation.', 19),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What is the role of the Supreme Court in civil rights?', 'It has both advanced rights (Brown) and restricted them (Plessy, Shelby County, Dobbs).', 20),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What is the role of Congress in civil rights?', 'Passing legislation such as the Civil Rights Act and Voting Rights Act.', 21),
  ('Politics', 'AQA', 'alevel', '2.8', 'Civil Rights', 'What is the role of the President in civil rights?', 'Using executive orders, appointments and political leadership, e.g. Truman desegregating the armed forces (1948).', 22),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'What is a codified constitution?', 'A constitution set out in a single authoritative document.', 1),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'Why is the US Constitution harder to change than the UK''s?', 'It requires supermajorities in Congress and ratification by three-quarters of the states; the UK''s can be changed by ordinary legislation.', 2),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'What is constitutional sovereignty?', 'The constitution is the supreme source of authority, as in the USA.', 3),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'What is parliamentary sovereignty compared with constitutional sovereignty?', 'In the UK Parliament is supreme; in the US the Constitution is supreme.', 4),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'How is the UK constitution flexible?', 'It can adapt quickly through Acts of Parliament and changing conventions.', 5),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'How is the US constitution flexible?', 'Through judicial interpretation, e.g. the Commerce Clause and the living constitution approach.', 6),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'What is the difference in the territorial distribution of power?', 'The US is federal with entrenched state powers; the UK is unitary with devolution.', 7),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'Are UK and US constitutions similar in principles?', 'Both embody the rule of law, limited government, representative democracy and protection of rights.', 8),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'What is a similarity in the separation of powers?', 'Both have independent judiciaries, and both separate the judiciary from the other branches.', 9),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'What is a difference in the separation of powers?', 'The US separates personnel strictly; in the UK ministers sit in Parliament (fusion of powers).', 10),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'What is the structural explanation for constitutional stability in the US?', 'Entrenchment and the amendment process make formal change rare.', 11),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'What is the cultural explanation for US constitutional reverence?', 'Americans see the Constitution as a symbol of national identity and the founding.', 12),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'What is the cultural explanation for the UK''s uncodified constitution?', 'A tradition of gradual, evolutionary change and trust in Parliament.', 13),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'What is the rational explanation for UK governments not codifying?', 'Governments benefit from flexibility and parliamentary sovereignty, so have little incentive to limit their own power.', 14),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'How do devolved governments compare with US states?', 'US states have entrenched powers; devolved bodies have powers granted by Westminster.', 15),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'How do rights protections compare?', 'The US Bill of Rights is entrenched; the UK''s Human Rights Act can be amended by Parliament.', 16),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'How has UK devolution made it more like the US?', 'Power is more dispersed, with separate legislatures and policy divergence.', 17),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'How has the UK Supreme Court made the UK more like the US?', 'A separate, visible highest court has increased judicial prominence.', 18),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'What limits convergence between the two constitutions?', 'Parliamentary sovereignty, the lack of entrenchment, and the fusion of powers in the UK.', 19),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'What role do conventions play in both constitutions?', 'Both rely on conventions, e.g. the US two-term limit before the 22nd Amendment, and UK royal assent.', 20),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'What is judicial review''s role in both constitutions?', 'US courts can strike down laws; UK courts can review executive action but not overturn Acts of Parliament.', 21),
  ('Politics', 'AQA', 'alevel', '2.9', 'Comparative — Constitutional Arrangements', 'What is the significance of the age of the two constitutions?', 'The US has a single founding document (1787); the UK''s has evolved over centuries.', 22),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'How is the US President elected versus the UK PM?', 'The President is elected through the Electoral College; the PM is the leader of the largest party in the Commons.', 1),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'What fixed term does the US President have?', 'Four years, with a two-term limit (22nd Amendment).', 2),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'Does the UK PM have a fixed term?', 'No; the PM serves as long as they keep the confidence of the Commons and their party, with elections at least every five years.', 3),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'How can a US President be removed?', 'By impeachment and conviction, or under the 25th Amendment.', 4),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'How can a UK PM be removed?', 'By losing a vote of no confidence, losing an election, or being replaced by their party.', 5),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'What is the difference between the US and UK Cabinets?', 'The US Cabinet is appointed from outside Congress and is advisory; the UK Cabinet is drawn from Parliament with collective responsibility.', 6),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'How does party support compare for the two executives?', 'The PM usually commands a disciplined majority; the President often faces divided government and weak party discipline.', 7),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'What is the President''s legislative power compared with the PM''s?', 'The President can veto and recommend legislation but can''t introduce it; the PM controls the legislative agenda.', 8),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'How does foreign policy power compare?', 'Both lead foreign policy; the President is constitutionally commander-in-chief, and the PM uses the royal prerogative (with a convention of consulting Parliament).', 9),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'What is the head of state difference?', 'The US President is head of state and head of government; the UK PM is head of government, with the monarch as head of state.', 10),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'What is the structural explanation for the PM''s legislative dominance?', 'The fusion of executive and legislature and a disciplined majority.', 11),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'What is the rational explanation for US presidential weakness in Congress?', 'Members of Congress are elected separately and respond to their own constituents.', 12),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'What is the cultural explanation for presidential personalisation?', 'The President is a national symbol and directly elected, creating a personal mandate.', 13),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'How do the executives compare in appointing judges?', 'The President nominates Supreme Court justices; UK PMs have no role in judicial selection.', 14),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'How do executive orders compare with UK secondary legislation?', 'Executive orders are issued by the President alone; UK statutory instruments rely on powers delegated by Parliament.', 15),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'What are the similarities between the two executives?', 'Both lead their party, set the policy agenda, command the armed forces, and dominate media attention.', 16),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'Which executive has more power in domestic policy?', 'The UK PM, if they have a large majority; the President faces more checks.', 17),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'Which executive has more security of tenure?', 'The President, who has a fixed term and is hard to remove.', 18),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'How have UK PMs been described as presidential?', 'Blair and Johnson were accused of personalised leadership, spatial leadership and use of special advisers.', 19),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'What is the imperial presidency compared with elective dictatorship?', 'Both describe concerns about excessive executive power in each system.', 20),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'How does the role of the Vice President compare with the Deputy PM?', 'The VP has constitutional roles (tie-breaking, succession); the UK Deputy PM has no formal constitutional role.', 21),
  ('Politics', 'AQA', 'alevel', '2.10', 'Comparative — The Executives', 'What is the difference in executive accountability?', 'The PM faces weekly PMQs; the President isn''t questioned directly by Congress.', 22),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'How are US Supreme Court justices appointed?', 'Nominated by the President and confirmed by a Senate majority.', 1),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'How are UK Supreme Court justices appointed?', 'By an independent selection commission, with the Lord Chancellor''s approval.', 2),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'What is the key difference in judicial power between the UK and US?', 'The US Supreme Court can strike down laws as unconstitutional; the UK Supreme Court can''t overturn Acts of Parliament.', 3),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'Why is the US Supreme Court more politicised?', 'Lifetime appointments, political nominations, Senate confirmation battles and rulings on contentious issues.', 4),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'How do tenure arrangements differ?', 'US justices serve for life; UK justices must retire at 75.', 5),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'What is a similarity between the two courts?', 'Both are independent, final courts of appeal that can rule on the lawfulness of executive actions.', 6),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'What is the difference in judicial review?', 'US courts review the constitutionality of laws; UK courts review the lawfulness of executive actions.', 7),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'What is the role of precedent in both systems?', 'Both follow stare decisis, although both top courts can depart from precedent.', 8),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'Why is the UK Supreme Court less prominent?', 'It lacks the power to strike down legislation, and appointments are non-political.', 9),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'How do confirmation processes compare?', 'US hearings are public and televised; UK appointments are made quietly by a commission.', 10),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'What is the cultural explanation for US judicial prominence?', 'Rights-based culture, reverence for the Constitution, and a history of landmark rulings.', 11),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'What is the structural explanation for judicial differences?', 'The US has an entrenched, codified constitution; the UK has parliamentary sovereignty.', 12),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'What is the rational explanation for politicised US appointments?', 'Presidents and senators know justices shape policy for decades, so they fight for ideological control.', 13),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'How do the courts protect rights in both countries?', 'The US Court enforces the Bill of Rights; the UK Court uses the Human Rights Act and common law.', 14),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'What is judicial activism in both systems?', 'Both courts have been accused of activism: the US over abortion and guns, the UK over Brexit and asylum.', 15),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'How can each court''s rulings be overturned?', 'US rulings require a constitutional amendment or later Court decision; UK rulings can be overturned by an Act of Parliament.', 16),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'What is the difference in the courts'' role in federalism and devolution?', 'The US Court arbitrates federal–state disputes; the UK Court rules on devolution issues.', 17),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'How diverse are the two courts?', 'Both have been criticised for lack of diversity; the US Court has recently become more diverse.', 18),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'What is the ideological balance of the US Court compared with the UK?', 'The US Court has a clear 6–3 conservative majority; UK justices aren''t seen as ideological.', 19),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'What was the effect of Dobbs (2022) on perceptions of the US Court?', 'It increased perceptions of politicisation and reduced public confidence in the Court.', 20),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'What was the effect of Miller II (2019) on perceptions of the UK Court?', 'It raised the Court''s profile and led to accusations that judges were political.', 21),
  ('Politics', 'AQA', 'alevel', '2.11', 'Comparative — The Judiciaries', 'What is the similarity in judicial independence?', 'Both judiciaries have security of tenure and independence from government interference.', 22),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'What electoral system do the UK and US use for their legislatures?', 'Both use FPTP in single-member constituencies.', 1),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'What party system is produced by FPTP?', 'Two-party dominance, as predicted by Duverger''s law.', 2),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'Why does the UK have more significant third parties than the US?', 'Regional concentration (SNP), historic parties (Lib Dems), and a parliamentary system that rewards regional strength.', 3),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'How do candidate selection processes compare?', 'US candidates are chosen by primaries (voters); UK candidates are chosen by local party members and central party.', 4),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'How does party discipline compare?', 'UK parties are highly disciplined through the whip and patronage; US parties are much weaker.', 5),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'How does campaign finance compare?', 'US campaigns cost billions with few limits; UK campaigns have strict spending limits.', 6),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'How does the frequency of elections compare?', 'US House elections are every two years; UK general elections are at least every five years.', 7),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'How do referendums compare?', 'The UK uses occasional national referendums; the US has no national referendums but many state-level initiatives.', 8),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'How does voter turnout compare?', 'Turnout is often lower in the US, especially in midterms, than in UK general elections.', 9),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'How does party ideology compare?', 'US parties are more polarised; UK parties vary but tend to converge more.', 10),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'What is the structural explanation for weak US parties?', 'Separation of powers, federalism and primaries weaken central party control.', 11),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'What is the rational explanation for party discipline in the UK?', 'MPs rely on the party for career advancement and re-election, so they follow the whip.', 12),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'What is the cultural explanation for US party differences?', 'Individualism and distrust of central authority lead to candidate-centred politics.', 13),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'How do the leadership selection processes compare?', 'UK party leaders are chosen by MPs and members; US parties have no formal leader outside Congress, and the presidential nominee leads.', 14),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'What is the role of television debates in both countries?', 'Established in the US since 1960; in the UK since 2010, with less impact.', 15),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'How does broadcast regulation differ?', 'UK broadcasters must be impartial and paid political TV ads are banned; US broadcasters are less regulated and ads are central.', 16),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'How do electoral systems for executives compare?', 'The President is elected by the Electoral College; the UK PM is not directly elected.', 17),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'What is the role of minor parties in both systems?', 'UK minor parties have more representation (SNP, Lib Dems), while US third parties are marginal.', 18),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'What is the effect of gerrymandering in both countries?', 'Significant in the US, where state legislatures draw districts; the UK uses independent Boundary Commissions.', 19),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'What is the similarity in voting behaviour?', 'Both show dealignment, increased volatility and education divides.', 20),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'What is the similarity in polarisation?', 'Both experienced polarisation around populist issues, e.g. Brexit and Trump.', 21),
  ('Politics', 'AQA', 'alevel', '2.12', 'Comparative — Electoral and Party Systems', 'Are the party systems converging?', 'Partly: both have seen populism and polarisation, but institutional differences remain.', 22),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'Why do US pressure groups have more access points?', 'The separation of powers and federalism give many targets: Congress, the President, the courts and states.', 1),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'Why do UK pressure groups target the executive?', 'Power is concentrated in the executive, which controls Parliament through its majority.', 2),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'How does campaign finance give US groups more power?', 'PACs and Super PACs allow groups to spend heavily on elections.', 3),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'How do groups use courts in both countries?', 'US groups use litigation and amicus briefs; UK groups use judicial review, but courts can''t overturn Acts.', 4),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'What are the similarities in pressure group methods?', 'Both use lobbying, protests, media campaigns and online activism.', 5),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'What is the role of think tanks in both countries?', 'Both have influential think tanks shaping policy, e.g. Heritage Foundation (US), IEA (UK).', 6),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'How does lobbying regulation compare?', 'The US requires lobbyist registration under the Lobbying Disclosure Act; the UK''s Lobbying Act 2014 is narrower.', 7),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'What is the revolving door in both countries?', 'Former politicians and officials become lobbyists or company directors in both systems.', 8),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'What is the structural explanation for US group power?', 'Weak parties, the separation of powers and federalism create more influence opportunities.', 9),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'What is the rational explanation for groups targeting Congress?', 'Individual members of Congress are more independent and responsive to donors and constituents.', 10),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'What is the cultural explanation for pressure group activity?', 'A US culture of individualism, rights and litigation encourages group activity.', 11),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'How has UK group activity become more like the US?', 'More use of judicial review, professional lobbying and social media campaigns.', 12),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'Why can''t UK groups use courts as effectively?', 'Parliamentary sovereignty means courts can''t strike down legislation.', 13),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'How do trade unions compare?', 'Both have declining union membership; UK unions are formally linked to Labour, US unions support Democrats informally.', 14),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'How do business groups compare?', 'Business groups are powerful in both, but the US allows greater corporate political spending.', 15),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'What is the role of social movements in both countries?', 'Movements like BLM and climate activism operate in both, using protests and social media.', 16),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'What is the role of pluralism in both systems?', 'Both are seen as pluralist democracies, but critics argue elites dominate.', 17),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'What is the importance of insider status in both systems?', 'Insider status matters more in the UK, where access to ministers is key.', 18),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'How do the two countries compare on protest rights?', 'The US First Amendment protects protest; UK protest rights are protected by the HRA but restricted by recent laws.', 19),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'What is the impact of money on pressure groups in both countries?', 'Wealthier groups have more influence in both, but especially in the US due to campaign finance.', 20),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'What is the effect of devolution on UK pressure groups?', 'It creates additional access points in Scotland, Wales and Northern Ireland.', 21),
  ('Politics', 'AQA', 'alevel', '2.13', 'Comparative — Pressure Groups', 'Which country''s pressure groups are more powerful?', 'US groups, due to more access points, campaign finance and weaker parties.', 22),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'What is the legal basis of rights in the US?', 'The Bill of Rights and other amendments, entrenched in the Constitution.', 1),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'What is the legal basis of rights in the UK?', 'The Human Rights Act 1998, common law, and statutes such as the Equality Act 2010.', 2),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'Can UK courts strike down laws that violate rights?', 'No; they can issue a declaration of incompatibility, but Parliament decides whether to act.', 3),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'Can US courts strike down laws that violate rights?', 'Yes; the Supreme Court can declare laws unconstitutional.', 4),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'Why are US rights more secure in theory?', 'They are entrenched and protected by an independent court with strike-down powers.', 5),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'Why might UK rights be more secure in practice?', 'Strong political culture, cross-party consensus on core rights, and the European Convention.', 6),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'How does rights uniformity compare?', 'UK rights are uniform across the country; US rights can vary between states, e.g. abortion after Dobbs.', 7),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'How did civil rights advance in the US?', 'Through litigation (Brown), direct action (Montgomery), and legislation (Civil Rights Act 1964).', 8),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'How did civil rights advance in the UK?', 'Mainly through legislation, e.g. the Race Relations Act 1965 and the Equality Act 2010.', 9),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'What is the role of pressure groups in rights in both countries?', 'Groups like the ACLU (US) and Liberty (UK) campaign and litigate.', 10),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'How do the two countries compare on abortion rights?', 'UK abortion is legal under the Abortion Act 1967 (decriminalised in Northern Ireland in 2019); US abortion now depends on state law after Dobbs.', 11),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'How do the two countries compare on gun rights?', 'The US protects gun ownership in the Second Amendment; the UK has strict gun control.', 12),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'How do the two countries compare on LGBTQ+ rights?', 'Same-sex marriage was legalised by statute in the UK (England and Wales 2013, Scotland 2014, Northern Ireland 2020) and by the Supreme Court in the US (Obergefell, 2015).', 13),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'How do the two countries compare on free speech?', 'The US First Amendment gives very broad protection; UK free speech is qualified, e.g. hate speech laws.', 14),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'What is the structural explanation for rights differences?', 'The US has an entrenched Bill of Rights enforced by courts; the UK relies on parliamentary sovereignty.', 15),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'What is the cultural explanation for rights differences?', 'US political culture emphasises individual rights and litigation; UK culture relies on Parliament and conventions.', 16),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'What is the rational explanation for rights differences?', 'UK governments prefer flexibility and avoid entrenchment; US actors use courts strategically.', 17),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'What is the paradox of rights security?', 'Entrenched US rights can still be reversed by the Court (Dobbs), while unentrenched UK rights have been stable.', 18),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'What is the role of the ECHR in the UK?', 'The UK remains a member of the Council of Europe, and the Strasbourg court provides external rights protection.', 19),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'What are the debates about replacing the Human Rights Act?', 'Conservatives proposed a British Bill of Rights (dropped in 2023); critics argued it would weaken rights.', 20),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'What is the similarity in rights protection?', 'Both have independent judiciaries, active civil society, and a commitment to the rule of law.', 21),
  ('Politics', 'AQA', 'alevel', '2.14', 'Comparative — Civil Rights', 'Which system protects rights better?', 'There is no simple answer: the US has stronger legal protection, but the UK has more uniform rights and political consensus.', 22),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is individualism in liberalism?', 'The belief in the primacy of the individual over any social group or collective.', 1),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is classical liberalism?', 'Early liberalism emphasising individual freedom, a minimal state and free markets.', 2),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is modern liberalism?', 'Liberalism accepting that the state should intervene to enable individuals to achieve their potential (positive freedom).', 3),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is the social contract?', 'The idea that the state''s authority rests on the consent of the governed.', 4),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is Locke''s view of the state?', 'The state exists to protect natural rights to life, liberty and property, based on consent; people may rebel if it fails.', 5),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is limited government?', 'Government power restricted by a constitution, rights and the separation of powers.', 6),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is tolerance in liberalism?', 'Accepting views and lifestyles one disagrees with, as long as they don''t harm others.', 7),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is the liberal view of human nature?', 'Humans are rational and self-interested, but capable of reasoning and progress.', 8),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is Mill''s view of liberty?', 'Individuals should be free to act as they wish, as long as they don''t harm others (the harm principle).', 9),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is Wollstonecraft''s contribution to liberalism?', 'She argued women are rational beings entitled to the same rights and education as men.', 10),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is Rawls''s theory of justice?', 'A just society is one people would choose behind a veil of ignorance, with equal liberties and inequalities only if they benefit the least well off.', 11),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is Friedan''s contribution to liberalism?', 'She argued women were trapped in domestic roles ("the problem that has no name") and campaigned for legal equality.', 12),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is the liberal view of the economy?', 'Classical liberals support free markets; modern liberals support a mixed economy with state intervention (Keynesianism).', 13),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is the liberal view of society?', 'Society is a collection of individuals; modern liberals accept that social conditions affect individuals'' freedom.', 14),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is meritocracy?', 'A society where success is based on ability and effort rather than birth or privilege.', 15),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is liberal democracy?', 'A democracy with free elections, the rule of law, protection of rights and limited government.', 16),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is the rule of law?', 'Everyone, including government, is subject to the law.', 17),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is equality of opportunity?', 'Everyone should have the same chance to succeed, regardless of background.', 18),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is foundational equality?', 'All humans are born with equal worth and rights.', 19),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is formal equality?', 'All individuals have the same legal and political rights.', 20),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'What is the liberal view of the state?', 'The state is a necessary evil (classical) or an enabler of freedom (modern).', 21),
  ('Politics', 'AQA', 'alevel', '3.1', 'Liberalism', 'Why do liberals fear the tyranny of the majority?', 'Majorities may oppress minorities and limit individual freedom, so rights must be protected.', 22),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is traditional conservatism?', 'A conservatism that values tradition, hierarchy, organic society and gradual change, based on Burke.', 1),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is paternalism?', 'The idea that those with power and wealth have a duty to look after those less fortunate (noblesse oblige).', 2),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is the organic society?', 'Society is like a living organism, with interdependent parts, which develops naturally over time.', 3),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is pragmatism in conservatism?', 'Making decisions based on practical circumstances rather than abstract principles or ideology.', 4),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is conservatism''s view of human nature?', 'Humans are imperfect: morally, intellectually and psychologically, so need order and authority.', 5),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is One Nation conservatism?', 'Disraeli''s idea that society is united and the wealthy have a duty to help the poor, to prevent social division.', 6),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is the New Right?', 'A combination of neoliberalism (free markets) and neoconservatism (social order and authority).', 7),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is neoliberalism?', 'An ideology supporting free markets, deregulation, privatisation and a minimal state in the economy.', 8),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is neoconservatism?', 'An ideology stressing traditional values, law and order, national identity and a strong state.', 9),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is libertarianism?', 'An ideology prioritising individual liberty and a minimal state.', 10),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is Hobbes''s view of the state of nature?', 'Life without government would be "nasty, brutish and short", so people accept a strong sovereign for security.', 11),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is Burke''s view of change?', 'Change should be gradual and organic, preserving the wisdom of tradition, as opposed to revolution.', 12),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is Oakeshott''s view of politics?', 'Politics should be pragmatic and based on experience, not rationalist blueprints or ideology.', 13),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is Rand''s objectivism?', 'A philosophy that rational self-interest is moral and laissez-faire capitalism is the ideal system.', 14),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is Nozick''s view of the state?', 'Only a minimal state protecting rights is justified; redistributive taxation violates self-ownership.', 15),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is the conservative view of property?', 'Property ownership gives security, encourages responsibility and respect for the law.', 16),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is the conservative view of the state?', 'The state should maintain order and authority; traditional conservatives accept intervention, the New Right wants a smaller state in the economy.', 17),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is the conservative view of the economy?', 'Traditional conservatives are pragmatic about intervention; neoliberals favour free markets.', 18),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is a tension between neoliberalism and neoconservatism?', 'Neoliberals want individual freedom and a small state; neoconservatives want a strong state enforcing social order and morality.', 19),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is authority in conservatism?', 'Authority comes from above and is natural and necessary to maintain order.', 20),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is hierarchy in conservatism?', 'Society is naturally hierarchical, with people in different positions performing different roles.', 21),
  ('Politics', 'AQA', 'alevel', '3.2', 'Conservatism', 'What is the conservative view of human rationality?', 'Human reason is limited, so tradition and experience are better guides than abstract theory.', 22),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is collectivism?', 'The belief that collective action is more effective than individual action in achieving social and economic goals.', 1),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is common ownership?', 'Productive resources should be owned collectively, by the state or workers, rather than privately.', 2),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is social justice?', 'A fair distribution of wealth, opportunities and privileges in society.', 3),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is equality of outcome?', 'An equal distribution of wealth and resources, which socialists see as necessary for true equality.', 4),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is the socialist view of human nature?', 'Humans are social, cooperative and shaped by their environment.', 5),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is revolutionary socialism?', 'The belief that capitalism must be overthrown by revolution, e.g. Marxism.', 6),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is evolutionary socialism?', 'The belief that socialism can be achieved gradually through democratic means and reform.', 7),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is social democracy?', 'A form of socialism accepting a mixed economy and capitalism with welfare state intervention to reduce inequality.', 8),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is the Third Way?', 'A revisionist approach combining market economics with social justice, associated with Giddens and New Labour.', 9),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is Marx''s view of class?', 'Society is divided into the bourgeoisie (owners) and proletariat (workers), whose conflict drives history.', 10),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is Webb''s contribution to socialism?', 'Beatrice Webb was a Fabian who argued socialism could be achieved gradually through reform and expertise.', 11),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is Luxemburg''s view of socialism?', 'Capitalism must be overthrown by a mass revolutionary movement, but socialism must be democratic.', 12),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is Crosland''s view of socialism?', 'Socialism is about equality and social justice, achievable within a mixed economy with welfare and education.', 13),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is Giddens''s view of socialism?', 'The Third Way: accept globalisation and markets while investing in human capital and social inclusion.', 14),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is the socialist view of the state?', 'Revolutionary socialists see the state as a tool of class oppression; social democrats see it as a means to achieve reform.', 15),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is the socialist view of the economy?', 'The economy should be run for social needs rather than profit, through common ownership or regulation.', 16),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is the socialist view of society?', 'Society is shaped by class and economic structures; inequality is caused by capitalism.', 17),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is workers'' control?', 'The idea that workers should manage their workplaces democratically.', 18),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is cooperation in socialism?', 'Humans naturally work together for mutual benefit rather than competing.', 19),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is fraternity?', 'The bonds of comradeship and solidarity between people.', 20),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is the socialist critique of capitalism?', 'It is exploitative, creates inequality, alienation, and instability.', 21),
  ('Politics', 'AQA', 'alevel', '3.3', 'Socialism', 'What is revisionist socialism?', 'Socialism that accepts capitalism can be reformed rather than abolished, seeking a fairer mixed economy (e.g. Bernstein, Crosland).', 22),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is nationalism?', 'The belief that the nation is the central principle of political organisation.', 1),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is liberal nationalism?', 'Nationalism based on self-determination, democracy and respect for other nations.', 2),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is conservative nationalism?', 'Nationalism emphasising tradition, national identity and social cohesion.', 3),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is anti-colonial nationalism?', 'Nationalism seeking independence from colonial rule.', 4),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is expansionist nationalism?', 'Aggressive nationalism seeking to expand a nation''s territory, often based on superiority.', 5),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is self-determination?', 'The right of a nation to govern itself.', 6),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is the nation-state?', 'A state whose borders match those of a nation.', 7),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is cultural nationalism?', 'Nationalism focusing on culture, language and traditions rather than political independence.', 8),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is ethnic nationalism?', 'Nationalism based on a shared ethnicity or ancestry.', 9),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is civic nationalism?', 'Nationalism based on shared values and citizenship rather than ethnicity.', 10),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is Garvey''s contribution to nationalism?', 'He promoted Black nationalism and pan-Africanism, encouraging pride and self-reliance.', 11),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is Mazzini''s contribution to nationalism?', 'He promoted Italian unification and liberal nationalism based on self-determination.', 12),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is Maurras''s contribution to nationalism?', 'He promoted integral nationalism, an authoritarian and exclusive form of French nationalism.', 13),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is chauvinism?', 'The belief in the superiority of one''s own nation.', 14),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is racialism?', 'The belief that races are distinct and should be separated, used in expansionist nationalism.', 15),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is the nationalist view of human nature?', 'Humans naturally form communities and have a need to belong to a nation.', 16),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is the nationalist view of the state?', 'Each nation should have its own state.', 17),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is the nationalist view of society?', 'Society is based on a shared national identity.', 18),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is the nationalist view of the economy?', 'Varies: some favour protectionism and economic self-sufficiency.', 19),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is internationalism?', 'Cooperation between nations; liberal nationalists support it, while expansionists reject it.', 20),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What is pan-nationalism?', 'A movement to unite all members of a nation or ethnic group, e.g. pan-Africanism.', 21),
  ('Politics', 'AQA', 'alevel', '3.4', 'Nationalism', 'What are the criticisms of nationalism?', 'It can lead to conflict, exclusion of minorities and aggression.', 22),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is liberal feminism?', 'Feminism seeking legal and political equality for women within the existing system through reform.', 1),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is radical feminism?', 'Feminism arguing that patriarchy pervades all aspects of society and must be overthrown.', 2),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is socialist feminism?', 'Feminism arguing that patriarchy is linked to capitalism, which exploits women''s unpaid domestic labour.', 3),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is postmodern feminism?', 'Feminism rejecting the idea of a single female experience and challenging fixed categories of gender.', 4),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is intersectionality?', 'The idea that different forms of oppression (race, class, gender) interact.', 5),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is the first wave of feminism?', 'The 19th and early 20th century movement for legal and political rights, especially suffrage.', 6),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is the second wave of feminism?', 'The 1960s–80s movement challenging social and cultural inequalities, e.g. in the family and workplace.', 7),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is the third wave of feminism?', 'Feminism from the 1990s emphasising diversity and individual identity.', 8),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is equality feminism?', 'The belief that women and men are fundamentally equal and should be treated the same.', 9),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is difference feminism?', 'The belief that women and men are different, and women''s differences should be celebrated.', 10),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is Millett''s contribution to feminism?', 'Sexual Politics (1970) argued patriarchy operates through all social institutions, especially the family.', 11),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is Rowbotham''s contribution to feminism?', 'A socialist feminist who argued women''s oppression is linked to capitalism and class.', 12),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is the feminist view of human nature?', 'Equality feminists argue gender is socially constructed; difference feminists see natural differences.', 13),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is the feminist view of the state?', 'Liberal feminists see the state as a tool for reform; radical feminists see it as patriarchal.', 14),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is the feminist view of the economy?', 'Socialist feminists highlight unpaid domestic labour and economic exploitation of women.', 15),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is the feminist view of society?', 'Society is patriarchal, with women systematically disadvantaged.', 16),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is the public/private divide?', 'The separation of politics (public, male) from the family (private, female), which feminists challenge.', 17),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is gender?', 'The socially constructed roles and behaviours associated with being male or female.', 18),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is sex?', 'The biological differences between males and females.', 19),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is the glass ceiling?', 'An invisible barrier preventing women from reaching senior positions.', 20),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What is the gender pay gap?', 'The difference in average earnings between men and women.', 21),
  ('Politics', 'AQA', 'alevel', '3.5', 'Feminism', 'What are the criticisms of feminism?', 'It is divided, may not represent all women, and some argue equality has largely been achieved.', 22),
  ('Politics', 'AQA', 'alevel', '3.6', 'Multiculturalism', 'What is multiculturalism?', 'The idea that different cultures can coexist within a society, and that cultural diversity should be recognised and valued.', 1),
  ('Politics', 'AQA', 'alevel', '3.6', 'Multiculturalism', 'What is liberal multiculturalism?', 'Multiculturalism within a framework of liberal values, tolerance and individual rights.', 2),
  ('Politics', 'AQA', 'alevel', '3.6', 'Multiculturalism', 'What is pluralist multiculturalism?', 'Multiculturalism that accepts deep value diversity, without giving liberal values priority.', 3),
  ('Politics', 'AQA', 'alevel', '3.6', 'Multiculturalism', 'What is cosmopolitan multiculturalism?', 'Multiculturalism that celebrates cultural mixing and a global identity.', 4),
  ('Politics', 'AQA', 'alevel', '3.6', 'Multiculturalism', 'What is conservative multiculturalism?', 'A critique suggesting diversity may undermine national identity and social cohesion.', 5),
